c.cpp:
class Solution {
public:
    int findChampion(vector<vector<int>>& grid) {
        int n = grid.size();
        for (int i = 0; i < n; i++) {
            int s = 0;
            for (int j = 0; j < n; j++) s += grid[i][j];
            if (s == n - 1) return i;
        }
        return -1;
    }
};

